// 1. HARDCODED PREFERENCES (Edit these here)
const query = $('User Input').first().json.role;
const loc = $('User Input').first().json.location;
const wantRemote = false; // Set to true if you ONLY want remote jobs

// 2. Build URL Manually
// We use encodeURIComponent to ensure spaces and symbols are safe
const baseUrl = 'https://www.linkedin.com/jobs/search?';

// Create the list of parameters
const params = [
  'keywords=' + encodeURIComponent(query),
  'location=' + encodeURIComponent(loc),
  'trk=public_jobs_jobs-search-bar_search-submit',
  'f_TPR=r86400' // Last 24 hours only
];

// Check for Remote (f_WT=2)
if (wantRemote === true) {
  params.push('f_WT=2');
}

// Join them together with "&"
const targetUrl = baseUrl + params.join('&');

return {
  json: {
    url: targetUrl
  }
};

const data = $input.first().json;
const titles = data.title || [];
const companies = data.company || [];
const locations = data.location || [];
const links = data.link || [];

const results = [];
const seenCompanies = new Set();

for (let i = 0; i < titles.length; i++) {

  // 1. Clean Company Name
  let cleanCompany = companies[i] || "Unknown";
  if (cleanCompany.includes('\n')) cleanCompany = cleanCompany.split('\n')[0].trim();

  const link = links[i] || "";

  // 2. Deduplication (Unique Companies only)
  if (!seenCompanies.has(cleanCompany)) {

    // 3. 🆔 EXTRACT JOB ID (Crucial New Step)
    // We look for the number inside the URL (e.g. view/3748291...)
    let jobId = "0";
    const idMatch = link.match(/view\/(\d+)/) || link.match(/-(\d+)\?/);

    if (idMatch) {
      jobId = idMatch[1];
    }

    // Only proceed if we found a valid ID
    if (jobId !== "0") {
        results.push({
            json: {
              title: titles[i] ? titles[i].trim() : "Unknown",
              company: cleanCompany,
              location: locations[i] ? locations[i].trim() : "Unknown",
              link: link,
              jobId: jobId // <--- Pass this to the next node
            }
        });
        seenCompanies.add(cleanCompany);
    }
  }
}

// ⚠️ LIMIT TO 8 JOBS
// Since we are looping (Deep Scraping), we limit to 8 to avoid bans.
return results.slice(0, 8);

// 1. Get AI Agent output (ranked jobs as a string)
const aiText = $input.first().json.output || $input.first().json.text || "";

// --- DEBUG: keep a copy of raw AI output in case something breaks
// You will see this in the node's JSON output under "debug_raw_ai"
let debug_raw_ai = aiText;

try {
  // 2. Remove ```json ``` fences if present
  let cleaned = aiText.replace(/```json/g, "").replace(/```/g, "").trim();

  // 3. If there is surrounding text, try to isolate the JSON array [ ... ]
  const match = cleaned.match(/\[[\s\S]*\]/);
  if (match) cleaned = match[0];

  // 4. Parse the JSON array from the AI
  let rankedJobs = JSON.parse(cleaned);
  if (!Array.isArray(rankedJobs)) rankedJobs = [rankedJobs];

  // 5. Get the original enriched jobs (with full_description/description)
  //    IMPORTANT: name here must match your aggregator node name on the canvas
  const originalJobs = $node["Code in JavaScript4"].json.job_list || [];

  // Helper: find original job by link
  function findOriginal(link) {
    return originalJobs.find(j => j.link === link) || {};
  }

  // 6. Build email body + jobs_raw including description
  let message = "🚀 **Top Jobs Found Today:**\n\n";
  const jobs_raw = [];

  rankedJobs.slice(0, 5).forEach((j, index) => {
    const orig = findOriginal(j.link);

    const company = j.company   || orig.company   || "Unknown";
    const title   = j.title     || orig.title     || "Job Title";
    const loc     = j.location  || orig.location  || "Location not specified";
    const pitch   = j.pitch     || "Check details.";
    const link    = j.link      || orig.link      || "#";

    // We prefer the original scraped description
    const description = orig.description || orig.full_description || j.description || "";

    message += `${index + 1}. **${company}** - ${title}\n`;
    message += `📍 ${loc}\n`;
    message += `💡 ${pitch}\n`;
    message += `🔗 ${link}\n\n`;

    jobs_raw.push({
      company,
      title,
      location: loc,
      pitch,
      link,
      description
    });
  });

  // 7. Return single item for the rest of the flow
  return [
    {
      json: {
        email_body: message,   // used by Gmail
        jobs_raw,              // used by Split Out → Writer AI → Notion
        debug_raw_ai           // helpful if something fails later
      }
    }
  ];

} catch (error) {
  // If anything fails, surface a helpful error and the raw AI text
  return [
    {
      json: {
        email_body: "⚠️ Error parsing AI results.",
        error: error.message,
        debug_raw_ai
      }
    }
  ];
}

// 1. Get the original info (Title, Link)
// We reference the NAME of your loop node exactly:
const originalJob = $('Loop Over Items').first().json;

// 2. Get the new description we just found
const desc = $input.first().json.description_text || "No description available.";

// 3. SLEEP (Anti-Ban) - Wait 1.5 seconds
const end = Date.now() + 1500;
while (Date.now() < end) continue;

return {
  json: {
    ...originalJob, 
    full_description: desc.substring(0, 3000) 
  }
};

// create an empty array to store the clean job list
const formattedJobs = [];

// Loop through all items coming from the previous node
for (const item of items) {
  formattedJobs.push({
    title: item.json.title,
    company: item.json.company,
    location: item.json.location,
    link: item.json.link,
    // You asked to include the description as well:
    description: item.json.full_description 
  });
}

// Return the specific format you requested:
// A single item containing a "job_list" array
return [
  {
    json: {
      job_list: formattedJobs
    }
  }
];

// Get the raw output from the AI Agent
const rawOutput = items[0].json.output;
let jobItems = [];

try {
    // 1. CLEANUP: Extract the JSON array
    // We look for the first '[' and last ']' to ignore any "Here is your JSON" text
    const start = rawOutput.indexOf('['); 
    const end = rawOutput.lastIndexOf(']');

    if (start !== -1 && end !== -1) {
        const jsonString = rawOutput.substring(start, end + 1);
        const jobs = JSON.parse(jsonString);

        // 2. PREPARE ITEMS FOR NOTION
        jobItems = jobs.map(job => {
            return {
                json: {
                    company: job.company,
                    title: job.title,
                    location: job.location,
                    pitch: job.pitch,
                    link: job.link
                }
            };
        });
    }
} catch (error) {
    console.log("Error parsing:", error);
    return [{ json: { error: "Failed to parse job data" } }];
}

// Return separate items so Notion creates 1 row per job
return jobItems;
